import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Text,
  VStack,
  HStack,
  Grid,
  GridItem,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Select as CSelect,
  Switch as CSwitch,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Tag,
  useToast,
  Progress,
  Icon
} from '@chakra-ui/react';
import { FiDatabase, FiDownload, FiUpload, FiRefreshCcw, FiPlayCircle, FiSettings, FiSave, FiTrash2 } from 'react-icons/fi';

const pad2 = (n) => String(n).padStart(2, '0');
const normalizeTimeHHmm = (value) => {
  if (!value) return '03:00';
  if (typeof value === 'string' && /^\d{2}:\d{2}$/.test(value)) return value;
  if (typeof value === 'string' && /^(\d{1,2}):(\d{1,2})(?::\d{1,2})?$/.test(value)) {
    const [, h, m] = value.match(/(\d{1,2}):(\d{1,2})/);
    const hh = Math.min(23, Math.max(0, parseInt(h, 10)));
    const mm = Math.min(59, Math.max(0, parseInt(m, 10)));
    return `${pad2(hh)}:${pad2(mm)}`;
  }
  return '03:00';
};

const computeNextRunLabel = (frequency, hhmm) => {
  try {
    const [hStr, mStr] = (hhmm || '03:00').split(':');
    const now = new Date();
    const next = new Date(now);
    next.setHours(parseInt(hStr || '3', 10), parseInt(mStr || '0', 10), 0, 0);
    if (next <= now) {
      if (frequency === 'daily') next.setDate(next.getDate() + 1);
      else if (frequency === 'weekly') next.setDate(next.getDate() + 7);
      else if (frequency === 'monthly') next.setMonth(next.getMonth() + 1);
      else next.setDate(next.getDate() + 1);
    }
    const dateStr = next.toLocaleDateString('ar-EG', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
    const timeStr = `${pad2(next.getHours())}:${pad2(next.getMinutes())}`;
    return `${dateStr} - ${timeStr}`;
  } catch {
    return '';
  }
};

const NewBackupSettings = () => {
  const toast = useToast();

  // Dark theme tokens
  const cardBg = '#0f212e';
  const cardBorder = '#3e5665';
  const headerBg = '#102a3a';
  const headerText = '#ffffff';
  const subText = '#a0aec0';
  const inputBg = '#0f212e';
  const inputText = '#e2e8f0';
  const inputBorder = '#3e5665';

  const [loading, setLoading] = useState(false);
  const [isCreatingBackup, setIsCreatingBackup] = useState(false);
  const [isRestoring, setIsRestoring] = useState(false);
  const [backupProgress, setBackupProgress] = useState(0);
  const [backupList, setBackupList] = useState([]);

  const [settings, setSettings] = useState({
    autoBackup: false,
    backupFrequency: 'daily',
    backupTime: '03:00',
    backupRetention: 30,
    backupEncryption: true
  });

  const nextRun = useMemo(() => computeNextRunLabel(settings.backupFrequency, normalizeTimeHHmm(settings.backupTime)), [settings.backupFrequency, settings.backupTime]);

  const loadBackupList = useCallback(async () => {
    try {
      const response = await fetch(getApiUrl(`/api/simple_backup.php?action=list&t=${Date.now()}`));
      const data = await response.json();
      if (data.success) setBackupList(data.backups || []);
    } catch (e) {
      console.error('Error loading backup list:', e);
    }
  }, []);

  useEffect(() => { loadBackupList(); }, [loadBackupList]);

  const handleManualBackup = async () => {
    setIsCreatingBackup(true);
    setBackupProgress(0);
    try {
      const interval = setInterval(() => setBackupProgress(prev => (prev >= 100 ? 100 : prev + 10)), 200);
      const res = await fetch(getApiUrl(`/api/simple_backup.php?action=create&t=${Date.now()}`), { method: 'POST', headers: { 'Content-Type': 'application/json' } });
      const data = await res.json();
      clearInterval(interval);
      setBackupProgress(100);
      if (data.success) {
        toast({ title: 'تم إنشاء النسخة الاحتياطية بنجاح', status: 'success' });
        loadBackupList();
      } else {
        toast({ title: data.message || 'حدث خطأ أثناء إنشاء النسخة الاحتياطية', status: 'error' });
      }
    } catch (e) {
      toast({ title: 'حدث خطأ أثناء إنشاء النسخة الاحتياطية', status: 'error' });
    } finally {
      setIsCreatingBackup(false);
      setTimeout(() => setBackupProgress(0), 500);
    }
  };

  const handleDeleteBackup = async (backupName) => {
    try {
      const res = await fetch(getApiUrl(`/api/simple_backup.php?action=delete&backup_name=${encodeURIComponent(backupName)}&t=${Date.now()}`), { method: 'POST' });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'تم حذف النسخة الاحتياطية', status: 'success' });
        loadBackupList();
      } else {
        toast({ title: data.message || 'فشل حذف النسخة', status: 'error' });
      }
    } catch (e) {
      toast({ title: 'فشل حذف النسخة الاحتياطية', status: 'error' });
    }
  };

  const handleRestoreBackup = async (backupName) => {
    if (!window.confirm(`هل أنت متأكد من استرجاع النسخة الاحتياطية "${backupName}"؟ سيتم استبدال جميع البيانات الحالية.`)) return;
    setIsRestoring(true);
    try {
      const res = await fetch(getApiUrl(`/api/simple_backup.php?action=restore&backup_name=${encodeURIComponent(backupName)}&t=${Date.now()}`), { method: 'POST' });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'تم استرجاع النسخة الاحتياطية', status: 'success' });
        loadBackupList();
      } else {
        toast({ title: data.message || 'فشل استرجاع النسخة', status: 'error' });
      }
    } catch (e) {
      toast({ title: 'فشل استرجاع النسخة الاحتياطية', status: 'error' });
    } finally {
      setIsRestoring(false);
    }
  };

  const handleDownloadBackup = (backupFile) => {
    const url = `/api/simple_backup.php?action=download&backup_name=${encodeURIComponent(backupFile)}&t=${Date.now()}`;
    window.open(url, '_blank');
  };

  const handleSave = async () => {
    setLoading(true);
    try {
      const normalizedTime = normalizeTimeHHmm(settings.backupTime);
      const payload = { ...settings, backupTime: normalizedTime };
      localStorage.setItem('backupSettings', JSON.stringify(payload));
      const res = await fetch(getApiUrl('/api/backup_settings_api.php'), {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'save_settings', settings: payload })
      });
      const data = await res.json();
      if (data.success) {
        toast({ title: 'تم حفظ إعدادات النسخ الاحتياطية', status: 'success' });
        if (payload.autoBackup) {
          await fetch(getApiUrl('/api/backup_scheduler.php'), {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action: 'schedule_backup', frequency: payload.backupFrequency, time: payload.backupTime })
          });
        }
      } else {
        toast({ title: data.message || 'حدث خطأ أثناء حفظ الإعدادات', status: 'error' });
      }
    } catch (e) {
      toast({ title: 'حدث خطأ أثناء حفظ الإعدادات', status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const resetSettings = () => {
    const defaults = { autoBackup: false, backupFrequency: 'daily', backupTime: '03:00', backupRetention: 30, backupEncryption: true };
    setSettings(defaults);
    toast({ title: 'تم إعادة تعيين الإعدادات', status: 'info' });
  };

  const loadSettings = async () => {
    try {
      const res = await fetch(getApiUrl('/api/backup_settings_api.php?action=get_settings'));
      const data = await res.json();
      if (data.success && data.settings) {
        const s = data.settings;
        s.backupTime = normalizeTimeHHmm(s.backupTime);
        setSettings(prev => ({ ...prev, ...s }));
      } else {
        const saved = localStorage.getItem('backupSettings');
        if (saved) {
          const s = JSON.parse(saved);
          s.backupTime = normalizeTimeHHmm(s.backupTime);
          setSettings(prev => ({ ...prev, ...s }));
        }
      }
    } catch (e) {
      const saved = localStorage.getItem('backupSettings');
      if (saved) {
        const s = JSON.parse(saved);
        s.backupTime = normalizeTimeHHmm(s.backupTime);
        setSettings(prev => ({ ...prev, ...s }));
      }
    }
  };

  useEffect(() => { loadSettings(); }, []);

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* Backup History */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3" justify="space-between">
              <HStack spacing="3">
                <Icon as={FiDatabase} color="blue.300" />
                <Heading size="sm" color={headerText}>تاريخ النسخ الاحتياطية</Heading>
              </HStack>
              <HStack spacing={3}>
                <Button leftIcon={<Icon as={FiPlayCircle} />} onClick={handleManualBackup} isLoading={isCreatingBackup} bg="#1475e1" _hover={{ bg: '#0e63c2' }} color="white">إنشاء نسخة احتياطية</Button>
                <Button leftIcon={<Icon as={FiRefreshCcw} />} onClick={loadBackupList} bg={cardBg} color={inputText} border="1px solid" borderColor={cardBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>تحديث</Button>
              </HStack>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            {isCreatingBackup && (
              <Box mb="4">
                <Text color={inputText} mb="2">جاري إنشاء النسخة الاحتياطية...</Text>
                <Progress value={backupProgress} />
              </Box>
            )}
            <Box border="1px solid" borderColor={cardBorder} borderRadius="lg" overflow="hidden">
              <Table variant="simple">
                <Thead bg="#0b1a24">
                  <Tr>
                    <Th color={inputText}>اسم النسخة</Th>
                    <Th color={inputText}>التاريخ</Th>
                    <Th color={inputText}>الحجم</Th>
                    <Th color={inputText}>الإجراءات</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {backupList.length === 0 ? (
                    <Tr>
                      <Td colSpan={4} textAlign="center" color={subText}>لا توجد نسخ احتياطية</Td>
                    </Tr>
                  ) : (
                    backupList.map((b) => (
                      <Tr key={b.name} _hover={{ bg: 'rgba(255,255,255,0.03)' }}>
                        <Td color={inputText}>{b.name}</Td>
                        <Td color={inputText}>{b.date}</Td>
                        <Td color={inputText}>{b.size}</Td>
                        <Td>
                          <HStack spacing={2}>
                            <Button size="sm" leftIcon={<Icon as={FiDownload} />} onClick={() => handleDownloadBackup(b.name)} bg={cardBg} color={inputText} border="1px solid" borderColor={cardBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>تحميل</Button>
                            <Button size="sm" leftIcon={<Icon as={FiUpload} />} onClick={() => handleRestoreBackup(b.name)} isLoading={isRestoring} bg="#1475e1" _hover={{ bg: '#0e63c2' }} color="white">استرجاع</Button>
                            <Button size="sm" leftIcon={<Icon as={FiTrash2} />} onClick={() => handleDeleteBackup(b.name)} colorScheme="red">حذف</Button>
                          </HStack>
                        </Td>
                      </Tr>
                    ))
                  )}
                </Tbody>
              </Table>
            </Box>
          </CardBody>
        </Card>

        {/* Backup Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3" justify="space-between">
              <HStack spacing="3">
                <Icon as={FiSettings} color="blue.300" />
                <Heading size="sm" color={headerText}>إعدادات النسخ الاحتياطية</Heading>
              </HStack>
              <Text color={subText} fontSize="sm">التنفيذ التالي: {nextRun || 'غير متاح'}</Text>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <SimpleGrid columns={{ base: 1, md: 2, lg: 5 }} spacing={4}>
              <FormControl>
                <FormLabel color={subText}>تكرار النسخ الاحتياطية</FormLabel>
                <CSelect value={settings.backupFrequency} onChange={(e) => setSettings(s => ({ ...s, backupFrequency: e.target.value }))} bg={inputBg} color={inputText} borderColor={inputBorder}>
                  <option value="daily">يومي</option>
                  <option value="weekly">أسبوعي</option>
                  <option value="monthly">شهري</option>
                </CSelect>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>وقت النسخ الاحتياطية</FormLabel>
                <Input type="time" value={normalizeTimeHHmm(settings.backupTime)} onChange={(e) => setSettings(s => ({ ...s, backupTime: normalizeTimeHHmm(e.target.value) }))} bg={inputBg} color={inputText} borderColor={inputBorder} />
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>فترة الاحتفاظ (يوم)</FormLabel>
                <NumberInput min={1} max={365} value={settings.backupRetention} onChange={(v) => setSettings(s => ({ ...s, backupRetention: Number(v) || 1 }))}>
                  <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                  <NumberInputStepper>
                    <NumberIncrementStepper />
                    <NumberDecrementStepper />
                  </NumberInputStepper>
                </NumberInput>
              </FormControl>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>النسخ تلقائي</FormLabel>
                <CSwitch isChecked={settings.autoBackup} onChange={(e) => setSettings(s => ({ ...s, autoBackup: e.target.checked }))} />
              </FormControl>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>تشفير النسخ</FormLabel>
                <CSwitch isChecked={settings.backupEncryption} onChange={(e) => setSettings(s => ({ ...s, backupEncryption: e.target.checked }))} />
              </FormControl>
            </SimpleGrid>
          </CardBody>
        </Card>

        {/* Save / Reset */}
        <HStack justify="center" bg="#0b1a24" p="4" borderRadius="xl">
          <HStack spacing={3}>
            <Button leftIcon={<Icon as={FiRefreshCcw} />} onClick={resetSettings} bg={cardBg} color={inputText} border="1px solid" borderColor={cardBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>إعادة تعيين</Button>
            <Button leftIcon={<Icon as={FiSave} />} onClick={handleSave} isLoading={loading} bg="#1475e1" _hover={{ bg: '#0e63c2' }} color="white">حفظ إعدادات النسخ الاحتياطية</Button>
          </HStack>
        </HStack>
      </VStack>
    </Box>
  );
};

export default NewBackupSettings;
