import React, { useState } from 'react';
import { Box, Heading, HStack, VStack, Button } from '@chakra-ui/react';
import { FiHome, FiType, FiShield, FiCloud } from 'react-icons/fi';
import NewGeneralSettings from '../components/NewGeneralSettings';
import NewAppearanceSettings from '../components/NewAppearanceSettings';
import NewSecuritySettings from '../components/NewSecuritySettings';
import NewBackupSettings from '../components/NewBackupSettings';

const Settings = () => {
  const [activeTabIndex, setActiveTabIndex] = useState(0);

  const handleTabChange = (index) => {
    setActiveTabIndex(index);
  };

  return (
    <>
      {/* Header Section */}
      <Box mb="8">
        <HStack spacing="8" align="flex-start">
          {/* Title Section */}
          <VStack align="flex-start" spacing="2" flex="1" minW="300px">
            <Heading size="lg" className="stake-heading-3">
              إعدادات النظام
            </Heading>
          </VStack>
        </HStack>
      </Box>

      {/* Sidebar and Content Layout */}
      <HStack align="flex-start" spacing="6">
        {/* Sidebar Navigation */}
        <Box w="250px" p="4" bg="#0f212e" borderRadius="xl" border="1px solid" borderColor="gray.200">
          <VStack align="stretch" spacing="2">
            <Button
              leftIcon={<FiHome size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 0 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(0)}
              _hover={{ bg: "rgba(255, 255, 255, 0.1)" }}
              _active={{ bg: "rgba(255, 255, 255, 0.1)" }}
            >
              الإعدادات العامة
            </Button>
            <Button
              leftIcon={<FiType size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 1 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(1)}
              _hover={{ bg: "rgba(255, 255, 255, 0.1)" }}
              _active={{ bg: "rgba(255, 255, 255, 0.1)" }}
            >
              المظهر والخطوط
            </Button>
            <Button
              leftIcon={<FiShield size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 2 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(2)}
              _hover={{ bg: "rgba(255, 255, 255, 0.1)" }}
              _active={{ bg: "rgba(255, 255, 255, 0.1)" }}
            >
              الأمان والحماية
            </Button>
            <Button
              leftIcon={<FiCloud size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 3 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(3)}
              _hover={{ bg: "rgba(255, 255, 255, 0.1)" }}
              _active={{ bg: "rgba(255, 255, 255, 0.1)" }}
            >
              النسخ الاحتياطية
            </Button>
          </VStack>
        </Box>

        {/* Main Content */}
        <Box flex="1">
          <Box bg="#0f212e" borderRadius="xl" border="1px solid" borderColor="#3e5665" p="6">
            {activeTabIndex === 0 && <NewGeneralSettings />}
            {activeTabIndex === 1 && <NewAppearanceSettings />}
            {activeTabIndex === 2 && <NewSecuritySettings />}
            {activeTabIndex === 3 && <NewBackupSettings />}
          </Box>
        </Box>
      </HStack>
    </>
  );
};

export default Settings;