import React, { useState, useEffect } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import useCurrency from '../hooks/useCurrency';
import { useSettings } from '../contexts/SettingsContext';
import { 
  Box,
  Card, 
  CardHeader,
  CardBody,
  Heading,
  Text,
  VStack,
  HStack,
  SimpleGrid,
  Grid,
  GridItem,
  FormControl,
  FormLabel,
  Input, 
  Select,
  Switch as CSwitch,
  Button, 
  Image as CImage,
  useToast,
  Spinner,
  Center
} from '@chakra-ui/react';
import { HomeOutlined, UploadOutlined, DeleteOutlined, SaveOutlined, DollarOutlined } from '@ant-design/icons';

const NewGeneralSettings = () => {
  const toast = useToast();
  const { settings, reloadSettings } = useSettings();
  const currencyHook = useCurrency();
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isUploadingLogo, setIsUploadingLogo] = useState(false);

  // Dark palette tokens
  const cardBg = '#0f212e';
  const cardBorder = '#3e5665';
  const headerBg = '#102a3a';
  const headerText = '#ffffff';
  const subText = '#a0aec0';
  const inputBg = '#0f212e';
  const inputText = '#e2e8f0';
  const inputBorder = '#3e5665';

  // Identity state
  const [identityValues, setIdentityValues] = useState({
    systemName: '',
    companyName: ''
  });
  const [logoPreview, setLogoPreview] = useState('');

  // Currency state
  const [currencyValues, setCurrencyValues] = useState({
    currency_symbol: 'ج.م',
    currency_name: 'جنيه مصري',
    currency_code: 'EGP',
    currency_position: 'after',
    currency_decimals: '0',
    currency_thousands_separator: ',',
    currency_decimal_separator: '.',
    currency_show_symbol: true,
    currency_show_name: true
  });

  const loadSystemSettings = async () => {
    setLoading(true);
    try {
      const response = await fetch(getApiUrl('/api/load_system_settings.php'));
      const data = await response.json();
      if (data.success && data.settings) {
        const s = data.settings;
        setIdentityValues({
          systemName: s['system_name'] || settings.systemName || '',
          companyName: s['company_name'] || settings.companyName || ''
        });
        const logoValue = s['company_logo'] || settings.companyLogo || '';
        setLogoPreview(logoValue);
      }
    } catch (error) {
      console.error('Error loading system settings:', error);
      toast({ title: 'خطأ في تحميل الإعدادات', status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const loadCurrency = async () => {
    try {
      // Prefill from hook immediately
      if (currencyHook?.settings) {
        const s = currencyHook.settings;
        setCurrencyValues({
          currency_symbol: s['currency.symbol'] ?? 'ج.م',
          currency_name: s['currency.name'] ?? 'جنيه مصري',
          currency_code: s['currency.code'] ?? 'EGP',
          currency_position: s['currency.position'] ?? 'after',
          currency_decimals: s['currency.decimals'] ?? '0',
          currency_thousands_separator: s['currency.thousands_separator'] ?? ',',
          currency_decimal_separator: s['currency.decimal_separator'] ?? '.',
          currency_show_symbol: (s['currency.show_symbol'] ?? 'true') === 'true',
          currency_show_name: (s['currency.show_name'] ?? 'true') === 'true'
        });
      }
      const res = await fetch(getApiUrl('/api/load_system_settings.php'));
      const data = await res.json();
      if (data.success) {
        const s = data.settings;
        setCurrencyValues({
          currency_symbol: s['currency.symbol'] ?? 'ج.م',
          currency_name: s['currency.name'] ?? 'جنيه مصري',
          currency_code: s['currency.code'] ?? 'EGP',
          currency_position: s['currency.position'] ?? 'after',
          currency_decimals: s['currency.decimals'] ?? '0',
          currency_thousands_separator: s['currency.thousands_separator'] ?? ',',
          currency_decimal_separator: s['currency.decimal_separator'] ?? '.',
          currency_show_symbol: (s['currency.show_symbol'] ?? 'true') === 'true',
          currency_show_name: (s['currency.show_name'] ?? 'true') === 'true'
        });
      }
    } catch (e) {
      // ignore, we already set from hook
    }
  };

  useEffect(() => {
    loadSystemSettings();
    loadCurrency();
  }, []);

  const handleSave = async () => {
    setSaving(true);
    try {
      const settingsToUpdate = [
        { key: 'system_name', value: identityValues.systemName },
        { key: 'company_name', value: identityValues.companyName }
      ];

      const response = await fetch(getApiUrl('/api/update_system_settings.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_multiple_settings', settings: settingsToUpdate })
      });
      const data = await response.json();
      if (!data.success) throw new Error(data.message || 'save failed');

      const cv = currencyValues;
      const currencyPayload = {
        'currency.symbol': cv.currency_symbol,
        'currency.name': cv.currency_name,
        'currency.code': cv.currency_code,
        'currency.position': cv.currency_position,
        'currency.decimals': String(cv.currency_decimals ?? '0'),
        'currency.thousands_separator': cv.currency_thousands_separator,
        'currency.decimal_separator': cv.currency_decimal_separator,
        'currency.show_symbol': cv.currency_show_symbol ? 'true' : 'false',
        'currency.show_name': cv.currency_show_name ? 'true' : 'false'
      };
      const resCur = await fetch(getApiUrl('/api/update_system_settings.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          action: 'update_multiple_settings',
          settings: Object.entries(currencyPayload).map(([key, value]) => ({ key, value }))
        })
      });
      const dataCur = await resCur.json();
      if (!dataCur.success) throw new Error(dataCur.message || 'currency save failed');

      toast({ title: 'تم حفظ الإعدادات بنجاح', status: 'success' });
      await loadSystemSettings();
      await reloadSettings();
      window.dispatchEvent(new CustomEvent('currencyUpdated'));
    } catch (error) {
      console.error('Error saving settings:', error);
      toast({ title: 'خطأ في حفظ الإعدادات', status: 'error' });
    } finally {
      setSaving(false);
    }
  };

  const saveLogo = async (file) => {
    setIsUploadingLogo(true);
    try {
      const formData = new FormData();
      formData.append('logo', file);
      const response = await fetch(getApiUrl('/api/upload_logo.php'), { method: 'POST', body: formData });
      const data = await response.json();
      if (data.success) {
        setLogoPreview(data.logoUrl);
        await fetch(getApiUrl('/api/update_system_settings.php'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'update_multiple_settings', settings: [{ key: 'company_logo', value: data.logoUrl }] })
        });
        toast({ title: 'تم رفع الشعار بنجاح', status: 'success' });
      } else {
        toast({ title: 'خطأ في رفع الشعار', status: 'error' });
      }
    } catch (error) {
      console.error('Error uploading logo:', error);
      toast({ title: 'خطأ في رفع الشعار', status: 'error' });
    } finally {
      setIsUploadingLogo(false);
    }
  };

  if (loading) {
    return (
      <Center bg={cardBg} borderRadius="xl" p="12">
        <VStack spacing="4">
          <Spinner size="lg" color="blue.400" />
          <Text color={inputText}>جاري تحميل الإعدادات...</Text>
        </VStack>
      </Center>
    );
  }

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* Company Identity */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Box as={HomeOutlined} color="blue.300" />
              <Heading size="sm" color={headerText}>هوية الشركة</Heading>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <Grid templateColumns={{ base: '1fr', lg: '2fr 1fr' }} gap={6}>
              <GridItem>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl>
                    <FormLabel color={subText}>اسم النظام</FormLabel>
                    <Input 
                      value={identityValues.systemName}
                      onChange={(e) => setIdentityValues(v => ({ ...v, systemName: e.target.value }))}
                      placeholder="أدخل اسم النظام"
                      bg={inputBg}
                      color={inputText}
                      borderColor={inputBorder}
                      _hover={{ borderColor: inputBorder }}
                      _focus={{ 
                        borderColor: 'blue.400', 
                        boxShadow: '0 0 0 2px rgba(20,117,225,0.25)',
                        bg: inputBg
                      }}
                      _active={{ bg: inputBg }}
                    />
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>اسم الشركة</FormLabel>
                    <Input 
                      value={identityValues.companyName}
                      onChange={(e) => setIdentityValues(v => ({ ...v, companyName: e.target.value }))}
                      placeholder="أدخل اسم الشركة"
                      bg={inputBg}
                      color={inputText}
                      borderColor={inputBorder}
                      _hover={{ borderColor: inputBorder }}
                      _focus={{ 
                        borderColor: 'blue.400', 
                        boxShadow: '0 0 0 2px rgba(20,117,225,0.25)',
                        bg: inputBg
                      }}
                      _active={{ bg: inputBg }}
                    />
                  </FormControl>
                </SimpleGrid>
              </GridItem>
              <GridItem>
                <VStack align="stretch" spacing={3} bg="#1b2b38" borderRadius="xl" p="4" border="1px solid" borderColor={cardBorder}>
                  <Text fontWeight="semibold" color={subText}>شعار الشركة</Text>
                  <Box bg={cardBg} borderRadius="md" p="3" border="1px solid" borderColor={cardBorder} textAlign="center">
                      {logoPreview ? (
                      <Box position="relative" display="inline-block">
                        <CImage src={logoPreview} alt="Company Logo" boxSize="80px" objectFit="contain" borderRadius="md" border="1px solid" borderColor={cardBorder} />
                          <Button
                          colorScheme="red"
                          size="xs"
                          position="absolute"
                          top="-2"
                          right="-2"
                          borderRadius="full"
                          onClick={() => setLogoPreview('')}
                        >
                          <Box as={DeleteOutlined} />
                        </Button>
                      </Box>
                    ) : (
                      <Box w="80px" h="80px" border="2px dashed" borderColor={cardBorder} borderRadius="md" mx="auto" display="flex" alignItems="center" justifyContent="center" bg="#0b1a24">
                        <Box as={UploadOutlined} color={subText} />
                      </Box>
                    )}
                  </Box>
                  <HStack>
                    <Input
                      type="file"
                      accept="image/*"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) saveLogo(file);
                      }}
                      bg={inputBg}
                      color={inputText}
                      borderColor={cardBorder}
                      _focus={{ borderColor: 'blue.400' }}
                      sx={{ '::file-selector-button': { cursor: 'pointer' } }}
                    />
                    <Button isLoading={isUploadingLogo} bg="#0f212e" border="1px solid" borderColor={cardBorder} color={inputText} _hover={{ bg: 'rgba(255,255,255,0.06)' }} leftIcon={<Box as={UploadOutlined} />}>رفع الشعار</Button>
                  </HStack>
                </VStack>
              </GridItem>
            </Grid>
          </CardBody>
            </Card>

        {/* Currency Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Box as={DollarOutlined} color="blue.300" />
              <Heading size="sm" color={headerText}>إعدادات العملة</Heading>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={4} mb={4}>
              <FormControl>
                <FormLabel color={subText}>رمز العملة</FormLabel>
                <Input 
                  value={currencyValues.currency_symbol} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_symbol: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ 
                    borderColor: 'blue.400', 
                    boxShadow: '0 0 0 2px rgba(20,117,225,0.25)',
                    bg: inputBg
                  }}
                  _active={{ bg: inputBg }}
                />
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>اسم العملة</FormLabel>
                <Input 
                  value={currencyValues.currency_name} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_name: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ 
                    borderColor: 'blue.400', 
                    boxShadow: '0 0 0 2px rgba(20,117,225,0.25)',
                    bg: inputBg
                  }}
                  _active={{ bg: inputBg }}
                />
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>عدد الكسور</FormLabel>
                <Select 
                  value={currencyValues.currency_decimals} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_decimals: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ borderColor: 'blue.400', boxShadow: '0 0 0 2px rgba(20,117,225,0.25)' }}
                  _active={{ bg: inputBg }}
                  sx={{
                    option: {
                      bg: inputBg,
                      color: inputText
                    }
                  }}
                >
                  <option value="0">0</option>
                  <option value="2">2</option>
                  <option value="3">3</option>
                </Select>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>فاصل الآلاف</FormLabel>
                <Select 
                  value={currencyValues.currency_thousands_separator} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_thousands_separator: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ borderColor: 'blue.400', boxShadow: '0 0 0 2px rgba(20,117,225,0.25)' }}
                  _active={{ bg: inputBg }}
                  sx={{
                    option: {
                      bg: inputBg,
                      color: inputText
                    }
                  }}
                >
                  <option value=",">، ,</option>
                  <option value=" ">مسافة</option>
                  <option value=".">.</option>
                </Select>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>كود العملة</FormLabel>
                <Input 
                  value={currencyValues.currency_code} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_code: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ 
                    borderColor: 'blue.400', 
                    boxShadow: '0 0 0 2px rgba(20,117,225,0.25)',
                    bg: inputBg
                  }}
                  _active={{ bg: inputBg }}
                />
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>موضع العرض</FormLabel>
                <Select 
                  value={currencyValues.currency_position} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_position: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ borderColor: 'blue.400', boxShadow: '0 0 0 2px rgba(20,117,225,0.25)' }}
                  _active={{ bg: inputBg }}
                  sx={{
                    option: {
                      bg: inputBg,
                      color: inputText
                    }
                  }}
                >
                  <option value="before">قبل الرقم</option>
                  <option value="after">بعد الرقم</option>
                </Select>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>الفاصل العشري</FormLabel>
                <Select 
                  value={currencyValues.currency_decimal_separator} 
                  onChange={(e) => setCurrencyValues(v => ({ ...v, currency_decimal_separator: e.target.value }))} 
                  bg={inputBg} 
                  color={inputText} 
                  borderColor={inputBorder}
                  _hover={{ borderColor: inputBorder }}
                  _focus={{ borderColor: 'blue.400', boxShadow: '0 0 0 2px rgba(20,117,225,0.25)' }}
                  _active={{ bg: inputBg }}
                  sx={{
                    option: {
                      bg: inputBg,
                      color: inputText
                    }
                  }}
                >
                  <option value=".">.</option>
                  <option value=",">,</option>
                </Select>
              </FormControl>
            </SimpleGrid>
            <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>عرض الرمز</FormLabel>
                <CSwitch isChecked={currencyValues.currency_show_symbol} onChange={(e) => setCurrencyValues(v => ({ ...v, currency_show_symbol: e.target.checked }))} />
              </FormControl>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>عرض الاسم</FormLabel>
                <CSwitch isChecked={currencyValues.currency_show_name} onChange={(e) => setCurrencyValues(v => ({ ...v, currency_show_name: e.target.checked }))} />
              </FormControl>
            </SimpleGrid>
          </CardBody>
            </Card>

        {/* Save Button */}
        <HStack justify="center" bg="#0b1a24" p="4" borderRadius="xl">
          <Button
            onClick={handleSave}
            isLoading={saving}
            leftIcon={<Box as={SaveOutlined} />}
            bg="#1475e1"
            _hover={{ bg: '#0e63c2' }}
            color="white"
          >
            {saving ? 'جاري الحفظ...' : 'حفظ الإعدادات'}
          </Button>
        </HStack>
      </VStack>
    </Box>
  );
};

export default NewGeneralSettings;