import React, { useEffect } from 'react';
import { useSettings } from '../contexts/SettingsContext';

const FontApplier = () => {
  const { settings } = useSettings();

  useEffect(() => {
    if (settings && settings.fontFamily) {
      console.log('FontApplier: Applying font:', settings.fontFamily);
      // Apply font to entire system
      const fontFamily = settings.fontFamily;
      let fontFamilyValue;
      
      // Map font values to actual font families
      switch (fontFamily) {
        case 'Cairo':
          fontFamilyValue = 'Cairo';
          break;
        case 'Amiri':
          fontFamilyValue = 'Amiri';
          break;
        case 'Scheherazade':
          fontFamilyValue = 'Scheherazade New';
          break;
        case 'NotoSansArabic':
          fontFamilyValue = 'Noto Sans Arabic';
          break;
        case 'Tajawal':
          fontFamilyValue = 'Tajawal';
          break;
        case 'Changa':
          fontFamilyValue = 'Changa';
          break;
        case 'ElMessiri':
          fontFamilyValue = 'El Messiri';
          break;
        case 'MarkaziText':
          fontFamilyValue = 'Markazi Text';
          break;
        case 'Harmattan':
          fontFamilyValue = 'Harmattan';
          break;
        case 'ArefRuqaa':
          fontFamilyValue = 'Aref Ruqaa';
          break;
        case 'ReemKufi':
          fontFamilyValue = 'Reem Kufi';
          break;
        case 'Lalezar':
          fontFamilyValue = 'Lalezar';
          break;
        case 'Vibes':
          fontFamilyValue = 'Vibes';
          break;
        case 'AmiriQuran':
          fontFamilyValue = 'Amiri Quran';
          break;
        case 'Lateef':
          fontFamilyValue = 'Lateef';
          break;
        case 'Mirza':
          fontFamilyValue = 'Mirza';
          break;
        case 'Rubik':
          fontFamilyValue = 'Rubik';
          break;
        case 'PlaypenSansArabic':
          fontFamilyValue = 'Playpen Sans Arabic';
          break;
        case 'NotoNaskhArabic':
          fontFamilyValue = 'Noto Naskh Arabic';
          break;
        case 'NotoKufiArabic':
          fontFamilyValue = 'Noto Kufi Arabic';
          break;
        case 'Almarai':
          fontFamilyValue = 'Almarai';
          break;
        case 'IBMPlexSansArabic':
          fontFamilyValue = 'IBM Plex Sans Arabic';
          break;
        case 'CairoPlay':
          fontFamilyValue = 'Cairo Play';
          break;
        default:
          fontFamilyValue = 'Cairo';
      }
      
      console.log('FontApplier: Setting CSS font-family to:', fontFamilyValue);
      
      // Set CSS variable for all elements
      document.documentElement.style.setProperty('--font-family', `'${fontFamilyValue}'`);
      
      // Apply to body and html for immediate effect
      document.body.style.fontFamily = `'${fontFamilyValue}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
      document.documentElement.style.fontFamily = `'${fontFamilyValue}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
      
      // Apply to root element
      const rootElement = document.getElementById('root');
      if (rootElement) {
        rootElement.style.fontFamily = `'${fontFamilyValue}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
      }
      
      console.log('FontApplier: Font applied to document root, body, html, and root element');
    }
  }, [settings]);

  return null; // This component doesn't render anything
};

export default FontApplier;
