import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Text,
  VStack,
  HStack,
  Grid,
  GridItem,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Switch as CSwitch,
  Button,
  Progress,
  Tag,
  useToast,
  Icon
} from '@chakra-ui/react';
import { FiShield, FiLock, FiKey, FiClock, FiRefreshCw, FiSave, FiAlertTriangle } from 'react-icons/fi';

const NewSecuritySettings = () => {
  const toast = useToast();

  // Dark theme tokens
  const cardBg = '#0f212e';
  const cardBorder = '#3e5665';
  const headerBg = '#102a3a';
  const headerText = '#ffffff';
  const subText = '#a0aec0';
  const inputBg = '#0f212e';
  const inputText = '#e2e8f0';
  const inputBorder = '#3e5665';

  const [loading, setLoading] = useState(false);
  const [securityValues, setSecurityValues] = useState({
    passwordMinLength: 8,
    requireSpecialChars: true,
    requireNumbers: true,
    requireUppercase: true,
    passwordExpiry: 90,
    sessionTimeout: 30,
    maxLoginAttempts: 5,
    lockoutDuration: 15,
    twoFactorAuth: false,
    loginNotifications: true,
    suspiciousActivityAlerts: true,
    ipWhitelist: false,
    autoBackup: true,
    backupEncryption: true,
    backupRetention: 30,
    auditLogging: true,
    logRetention: 365,
    adminActionLogging: true
  });

  useEffect(() => {
    try {
      const saved = localStorage.getItem('securitySettings');
      if (saved) {
        setSecurityValues(prev => ({ ...prev, ...JSON.parse(saved) }));
      }
    } catch (e) {
      // ignore
    }
  }, []);

  const onNumChange = (key) => (valueString) => {
    const value = Number(valueString);
    setSecurityValues(s => ({ ...s, [key]: isNaN(value) ? s[key] : value }));
  };

  const onBoolChange = (key) => (e) => {
    const checked = e.target ? e.target.checked : e;
    setSecurityValues(s => ({ ...s, [key]: checked }));
  };

  const calculateSecurityLevel = useMemo(() => {
    const v = securityValues;
    let score = 0; let total = 0;
    // password
    if (v.passwordMinLength >= 8) score += 1; total += 1;
    if (v.requireSpecialChars) score += 1; total += 1;
    if (v.requireNumbers) score += 1; total += 1;
    if (v.requireUppercase) score += 1; total += 1;
    if (v.passwordExpiry <= 90) score += 1; total += 1;
    // session
    if (v.sessionTimeout <= 30) score += 1; total += 1;
    if (v.maxLoginAttempts <= 5) score += 1; total += 1;
    if (v.lockoutDuration >= 15) score += 1; total += 1;
    // advanced
    if (v.twoFactorAuth) score += 2; total += 2;
    if (v.loginNotifications) score += 1; total += 1;
    if (v.suspiciousActivityAlerts) score += 1; total += 1;
    if (v.ipWhitelist) score += 1; total += 1;
    // backup
    if (v.autoBackup) score += 1; total += 1;
    if (v.backupEncryption) score += 1; total += 1;
    if (v.backupRetention >= 30) score += 1; total += 1;
    // audit
    if (v.auditLogging) score += 1; total += 1;
    if (v.logRetention >= 365) score += 1; total += 1;
    if (v.adminActionLogging) score += 1; total += 1;
    const percentage = Math.round((score / Math.max(total, 1)) * 100);
    const level = percentage >= 80 ? 'عالي' : percentage >= 60 ? 'متوسط' : 'منخفض';
    const color = percentage >= 80 ? 'green' : percentage >= 60 ? 'orange' : 'red';
    return { percentage, level, color };
  }, [securityValues]);

  const handleSave = async () => {
    setLoading(true);
    try {
      localStorage.setItem('securitySettings', JSON.stringify(securityValues));
      toast({ title: 'تم حفظ إعدادات الأمان بنجاح', status: 'success' });
    } catch (e) {
      toast({ title: 'حدث خطأ أثناء حفظ الإعدادات', status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const resetSettings = () => {
    const defaults = {
      passwordMinLength: 8,
      requireSpecialChars: true,
      requireNumbers: true,
      requireUppercase: true,
      passwordExpiry: 90,
      sessionTimeout: 30,
      maxLoginAttempts: 5,
      lockoutDuration: 15,
      twoFactorAuth: false,
      loginNotifications: true,
      suspiciousActivityAlerts: true,
      ipWhitelist: false,
      autoBackup: true,
      backupEncryption: true,
      backupRetention: 30,
      auditLogging: true,
      logRetention: 365,
      adminActionLogging: true
    };
    setSecurityValues(defaults);
    toast({ title: 'تم إعادة تعيين الإعدادات', status: 'info' });
  };

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* Security Level */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={FiShield} color="blue.300" />
              <Heading size="sm" color={headerText}>مستوى الأمان</Heading>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <HStack spacing="6" align="center">
              <Box position="relative">
                <Progress value={calculateSecurityLevel.percentage} size="lg" colorScheme={calculateSecurityLevel.color} borderRadius="full" w="140px" bg="#0b1a24" />
              </Box>
              <VStack align="start" spacing={1}>
                <HStack>
                  <Text color={inputText} fontWeight="semibold">المستوى:</Text>
                  <Tag colorScheme={calculateSecurityLevel.color}>{calculateSecurityLevel.level}</Tag>
                </HStack>
                <Text color={subText}>النقاط: {calculateSecurityLevel.percentage}%</Text>
              </VStack>
            </HStack>
          </CardBody>
        </Card>

        <Grid templateColumns={{ base: '1fr', lg: '1fr 1fr' }} gap={6}>
          {/* Password Settings */}
          <GridItem>
            <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
              <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
                <HStack spacing="3">
                  <Icon as={FiLock} color="blue.300" />
                  <Heading size="sm" color={headerText}>إعدادات كلمة المرور</Heading>
                </HStack>
              </CardHeader>
              <CardBody bg="#1b2b38">
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl>
                    <FormLabel color={subText}>الحد الأدنى لطول كلمة المرور</FormLabel>
                    <NumberInput min={6} max={20} value={securityValues.passwordMinLength} onChange={onNumChange('passwordMinLength')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>انتهاء صلاحية كلمة المرور (يوم)</FormLabel>
                    <NumberInput min={30} max={365} value={securityValues.passwordExpiry} onChange={onNumChange('passwordExpiry')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </SimpleGrid>
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4} mt="4">
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>طلب أحرف خاصة</FormLabel>
                    <CSwitch isChecked={securityValues.requireSpecialChars} onChange={onBoolChange('requireSpecialChars')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>طلب أرقام</FormLabel>
                    <CSwitch isChecked={securityValues.requireNumbers} onChange={onBoolChange('requireNumbers')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>طلب أحرف كبيرة</FormLabel>
                    <CSwitch isChecked={securityValues.requireUppercase} onChange={onBoolChange('requireUppercase')} />
                  </FormControl>
                </SimpleGrid>
              </CardBody>
            </Card>
          </GridItem>

          {/* Session Settings */}
          <GridItem>
            <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
              <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
                <HStack spacing="3">
                  <Icon as={FiClock} color="blue.300" />
                  <Heading size="sm" color={headerText}>إعدادات الجلسة</Heading>
                </HStack>
              </CardHeader>
              <CardBody bg="#1b2b38">
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl>
                    <FormLabel color={subText}>مهلة الجلسة (دقيقة)</FormLabel>
                    <NumberInput min={5} max={120} value={securityValues.sessionTimeout} onChange={onNumChange('sessionTimeout')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>الحد الأقصى لمحاولات تسجيل الدخول</FormLabel>
                    <NumberInput min={3} max={10} value={securityValues.maxLoginAttempts} onChange={onNumChange('maxLoginAttempts')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>مدة القفل (دقيقة)</FormLabel>
                    <NumberInput min={5} max={60} value={securityValues.lockoutDuration} onChange={onNumChange('lockoutDuration')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                </SimpleGrid>
              </CardBody>
            </Card>
          </GridItem>

          {/* Advanced Security */}
          <GridItem>
            <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
              <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
                <HStack spacing="3">
                  <Icon as={FiKey} color="blue.300" />
                  <Heading size="sm" color={headerText}>الأمان المتقدم</Heading>
                </HStack>
              </CardHeader>
              <CardBody bg="#1b2b38">
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>المصادقة الثنائية</FormLabel>
                    <CSwitch isChecked={securityValues.twoFactorAuth} onChange={onBoolChange('twoFactorAuth')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>إشعارات تسجيل الدخول</FormLabel>
                    <CSwitch isChecked={securityValues.loginNotifications} onChange={onBoolChange('loginNotifications')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>تنبيهات النشاط المشبوه</FormLabel>
                    <CSwitch isChecked={securityValues.suspiciousActivityAlerts} onChange={onBoolChange('suspiciousActivityAlerts')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>قائمة IP المسموحة</FormLabel>
                    <CSwitch isChecked={securityValues.ipWhitelist} onChange={onBoolChange('ipWhitelist')} />
                  </FormControl>
                </SimpleGrid>
              </CardBody>
            </Card>
          </GridItem>

          {/* Backup & Audit */}
          <GridItem>
            <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
              <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
                <HStack spacing="3">
                  <Icon as={FiAlertTriangle} color="blue.300" />
                  <Heading size="sm" color={headerText}>النسخ الاحتياطي والمراجعة</Heading>
                </HStack>
              </CardHeader>
              <CardBody bg="#1b2b38">
                <SimpleGrid columns={{ base: 1, md: 2 }} spacing={4}>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>النسخ الاحتياطي التلقائي</FormLabel>
                    <CSwitch isChecked={securityValues.autoBackup} onChange={onBoolChange('autoBackup')} />
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>تشفير النسخ الاحتياطية</FormLabel>
                    <CSwitch isChecked={securityValues.backupEncryption} onChange={onBoolChange('backupEncryption')} />
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>فترة الاحتفاظ بالنسخ الاحتياطية (يوم)</FormLabel>
                    <NumberInput min={7} max={365} value={securityValues.backupRetention} onChange={onNumChange('backupRetention')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>تسجيل المراجعة</FormLabel>
                    <CSwitch isChecked={securityValues.auditLogging} onChange={onBoolChange('auditLogging')} />
                  </FormControl>
                  <FormControl>
                    <FormLabel color={subText}>فترة الاحتفاظ بالسجلات (يوم)</FormLabel>
                    <NumberInput min={30} max={1095} value={securityValues.logRetention} onChange={onNumChange('logRetention')}>
                      <NumberInputField bg={inputBg} color={inputText} borderColor={inputBorder} />
                      <NumberInputStepper>
                        <NumberIncrementStepper />
                        <NumberDecrementStepper />
                      </NumberInputStepper>
                    </NumberInput>
                  </FormControl>
                  <FormControl display="flex" alignItems="center">
                    <FormLabel mb="0" color={subText}>تسجيل إجراءات الإدارة</FormLabel>
                    <CSwitch isChecked={securityValues.adminActionLogging} onChange={onBoolChange('adminActionLogging')} />
                  </FormControl>
                </SimpleGrid>
              </CardBody>
            </Card>
          </GridItem>
        </Grid>

        {/* Save / Reset */}
        <HStack justify="center" bg="#0b1a24" p="4" borderRadius="xl">
          <HStack spacing={3}>
            <Button leftIcon={<Icon as={FiRefreshCw} />} onClick={resetSettings} bg={cardBg} color={inputText} border="1px solid" borderColor={cardBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>
              إعادة تعيين
            </Button>
            <Button leftIcon={<Icon as={FiSave} />} onClick={handleSave} isLoading={loading} bg="#1475e1" _hover={{ bg: '#0e63c2' }} color="white">
              حفظ إعدادات الأمان
            </Button>
          </HStack>
        </HStack>
      </VStack>
    </Box>
  );
};

export default NewSecuritySettings;
