import React, { useState, useEffect, useMemo } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Container,
  VStack,
  HStack,
  Text,
  Heading,
  Button,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Badge,
  Avatar,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  FormControl,
  FormLabel,
  Input,
  Select,
  Textarea,
  Divider,
  Flex,
  Spacer,
  IconButton,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  MenuDivider,
  Spinner,
  Center,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Radio,
  RadioGroup,
  Stack,
  InputGroup,
  InputLeftElement,
  InputRightElement,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  SimpleGrid,
  Icon,
} from '@chakra-ui/react';
import {
  FiSearch,
  FiPlus,
  FiMoreVertical,
  FiDollarSign,
  FiCheckCircle,
  FiXCircle,
  FiClock,
  FiEye,
  FiX,
  FiRefreshCw,
  FiUser,
  FiHash,
  FiBriefcase,
  FiTarget,
  FiTrash2,
} from 'react-icons/fi';
import useCurrency from '../hooks/useCurrency';
import dayjs from 'dayjs';

// دالة لحساب أول يوم عمل في الأسبوع (السبت) أو أول يوم عمل في الشهر
const calculateFirstWorkingDay = (date, salaryType) => {
  if (!date) return new Date().toISOString().split('T')[0];
  
  const selectedDate = dayjs(date);
  
  if (salaryType === 'Weekly') {
    // للراتب الأسبوعي: أول يوم عمل هو السبت (6)
    const dayOfWeek = selectedDate.day(); // 0 = الأحد, 6 = السبت
    let daysToSubtract = (dayOfWeek + 1) % 7; // تحويل إلى السبت
    return selectedDate.subtract(daysToSubtract, 'day').format('YYYY-MM-DD');
  } else {
    // للراتب الشهري: أول يوم عمل في الشهر (تخطي الجمعة والسبت)
    const firstDayOfMonth = selectedDate.startOf('month');
    let currentDay = firstDayOfMonth;
    
    // البحث عن أول يوم عمل (ليس جمعة ولا سبت)
    while (currentDay.day() === 5 || currentDay.day() === 6) { // 5 = الجمعة, 6 = السبت
      currentDay = currentDay.add(1, 'day');
    }
    
    return currentDay.format('YYYY-MM-DD');
  }
};

const PremiumAdvances = () => {
  const { formatCurrency: fmtCurrency } = useCurrency();
  const toast = useToast();
  
  // States
  const [loading, setLoading] = useState(false);
  const [advances, setAdvances] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [filteredEmployees, setFilteredEmployees] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [salaryTypeFilter, setSalaryTypeFilter] = useState('');
  
  // Modal states
  const { isOpen: isAddModalOpen, onOpen: onAddModalOpen, onClose: onAddModalClose } = useDisclosure();
  const { isOpen: isDetailsModalOpen, onOpen: onDetailsModalOpen, onClose: onDetailsModalClose } = useDisclosure();
  
  // Form states
  const [formData, setFormData] = useState({
    salary_type: 'Weekly',
    employee_id: '',
    advance_amount: '',
    duration: '',
    duration_type: 'weekly',
    notes: '',
    created_date: new Date().toISOString().split('T')[0], // Default to today
    start_date: '' // تاريخ بداية السلفة (أول يوم عمل)
  });
  const [selectedAdvance, setSelectedAdvance] = useState(null);
  const [installmentAmount, setInstallmentAmount] = useState(0);

  // Fetch advances
  const fetchAdvances = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.append('status', statusFilter);
      if (salaryTypeFilter) params.append('salary_type', salaryTypeFilter);
      
      const response = await fetch(getApiUrl(`/api/advances_api.php?action=get_advances&${params}`));
      const result = await response.json();
      
      if (result.success) {
        setAdvances(result.data || []);
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في جلب السلف',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Fetch employees
  const fetchEmployees = async () => {
    try {
      const response = await fetch(getApiUrl('/api/unified_employees_api.php?action=get_employees'));
      const result = await response.json();
      
      if (result.success) {
        setEmployees(result.data || []);
      }
    } catch (error) {
      console.error('Error fetching employees:', error);
    }
  };

  useEffect(() => {
    fetchAdvances();
    fetchEmployees();
  }, [statusFilter, salaryTypeFilter]);

  // Filter employees by salary type
  useEffect(() => {
    if (formData.salary_type) {
      const filtered = employees.filter(emp => emp.salary_type === formData.salary_type);
      setFilteredEmployees(filtered);
    } else {
      setFilteredEmployees(employees);
    }
  }, [formData.salary_type, employees]);

  // Calculate installment amount
  useEffect(() => {
    if (formData.advance_amount && formData.duration) {
      const amount = parseFloat(formData.advance_amount) || 0;
      const duration = parseInt(formData.duration) || 0;
      if (duration > 0) {
        setInstallmentAmount(amount / duration);
      } else {
        setInstallmentAmount(0);
      }
    } else {
      setInstallmentAmount(0);
    }
  }, [formData.advance_amount, formData.duration]);

  // Filtered advances
  const filteredAdvances = useMemo(() => {
    return advances.filter(advance => {
      const matchesSearch = !searchTerm || 
        (advance.employee_name && advance.employee_name.toLowerCase().includes(searchTerm.toLowerCase())) ||
        (advance.employee_code && advance.employee_code.toLowerCase().includes(searchTerm.toLowerCase()));
      return matchesSearch;
    });
  }, [advances, searchTerm]);

  // Handle create advance
  const handleCreateAdvance = async (activate = false) => {
    if (!formData.employee_id || !formData.advance_amount || !formData.duration) {
      toast({
        title: 'خطأ',
        description: 'يرجى ملء جميع الحقول المطلوبة',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(getApiUrl('/api/advances_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'create_advance',
          ...formData,
          advance_amount: parseFloat(formData.advance_amount),
          duration: parseFloat(formData.duration),
          created_date: formData.created_date || new Date().toISOString().split('T')[0],
          start_date: formData.start_date || calculateFirstWorkingDay(formData.created_date || new Date().toISOString().split('T')[0], formData.salary_type),
        }),
      });

      const result = await response.json();

      if (result.success) {
        if (activate) {
          // Activate the advance
          const activateResponse = await fetch(getApiUrl('/api/advances_api.php'), {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              action: 'activate_advance',
              advance_id: result.data.id,
            }),
          });

          const activateResult = await activateResponse.json();

          if (activateResult.success) {
            toast({
              title: 'نجح',
              description: 'تم إنشاء وتفعيل السلفة بنجاح',
              status: 'success',
              duration: 3000,
              isClosable: true,
            });
            onAddModalClose();
            resetForm();
            fetchAdvances();
          } else {
            toast({
              title: 'تحذير',
              description: 'تم إنشاء السلفة لكن فشل تفعيلها: ' + activateResult.message,
              status: 'warning',
              duration: 5000,
              isClosable: true,
            });
          }
        } else {
          toast({
            title: 'نجح',
            description: 'تم إنشاء السلفة بنجاح',
            status: 'success',
            duration: 3000,
            isClosable: true,
          });
          onAddModalClose();
          resetForm();
          fetchAdvances();
        }
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في إنشاء السلفة',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Handle activate advance
  const handleActivateAdvance = async (advanceId) => {
    if (!window.confirm('هل أنت متأكد من تفعيل هذه السلفة؟')) {
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(getApiUrl('/api/advances_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'activate_advance',
          advance_id: advanceId,
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: 'نجح',
          description: 'تم تفعيل السلفة بنجاح',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchAdvances();
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في تفعيل السلفة',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Handle cancel advance
  const handleCancelAdvance = async (advanceId) => {
    const advance = advances.find(a => a.id === advanceId);
    const message = advance?.status === 'activated' 
      ? 'هل أنت متأكد من إلغاء هذه السلفة المفعلة؟ سيتم حذف مبلغ السلفة من المستحقات والأقساط غير المدفوعة.'
      : 'هل أنت متأكد من إلغاء هذه السلفة؟';
    
    if (!window.confirm(message)) {
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(getApiUrl('/api/advances_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'cancel_advance',
          advance_id: advanceId,
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: 'نجح',
          description: 'تم إلغاء السلفة بنجاح',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchAdvances();
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في إلغاء السلفة',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Handle delete advance
  const handleDeleteAdvance = async (advanceId) => {
    const message = 'هل أنت متأكد من حذف هذه السلفة الملغاة؟ سيتم حذف السلفة وجميع سجلات الأقساط المرتبطة بها نهائياً.';
    
    if (!window.confirm(message)) {
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(getApiUrl('/api/advances_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'delete_advance',
          advance_id: advanceId,
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: 'نجح',
          description: 'تم حذف السلفة وجميع سجلات الأقساط بنجاح',
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        fetchAdvances();
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في حذف السلفة',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Handle view details
  const handleViewDetails = async (advance) => {
    setLoading(true);
    try {
      const response = await fetch(getApiUrl(`/api/advances_api.php?action=get_advance_details&advance_id=${advance.id}`));
      const result = await response.json();

      if (result.success) {
        setSelectedAdvance(result.data);
        onDetailsModalOpen();
      } else {
        toast({
          title: 'خطأ',
          description: result.message || 'فشل في جلب تفاصيل السلفة',
          status: 'error',
          duration: 3000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ في الاتصال بالخادم',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      salary_type: 'Weekly',
      employee_id: '',
      advance_amount: '',
      duration: '',
      duration_type: 'weekly',
      notes: '',
      created_date: new Date().toISOString().split('T')[0] // Default to today
    });
    setInstallmentAmount(0);
  };

  // Get status badge
  const getStatusBadge = (status) => {
    const statusMap = {
      pending: { color: 'yellow', label: 'معلقة' },
      activated: { color: 'green', label: 'مفعلة' },
      completed: { color: 'blue', label: 'مكتملة' },
      cancelled: { color: 'red', label: 'ملغاة' },
    };
    const statusInfo = statusMap[status] || { color: 'gray', label: status };
    return (
      <Badge colorScheme={statusInfo.color} variant="solid">
        {statusInfo.label}
      </Badge>
    );
  };

  // Get duration options
  const getDurationOptions = () => {
    if (formData.duration_type === 'weekly') {
      return [
        { value: '1', label: 'أسبوع' },
        { value: '2', label: 'أسبوعين' },
        { value: '3', label: '3 أسابيع' },
        { value: '4', label: '4 أسابيع' },
        { value: '4', label: 'شهر', isMonth: true }, // 1 month = 4 weeks
        { value: '8', label: 'شهرين', isMonth: true }, // 2 months = 8 weeks
        { value: '12', label: '3 شهور', isMonth: true }, // 3 months = 12 weeks
        { value: '16', label: '4 شهور', isMonth: true }, // 4 months = 16 weeks
        { value: '20', label: '5 شهور', isMonth: true }, // 5 months = 20 weeks
        { value: '24', label: '6 شهور', isMonth: true }, // 6 months = 24 weeks
      ];
    } else {
      return Array.from({ length: 12 }, (_, i) => ({
        value: String(i + 1),
        label: i === 0 ? 'شهر' : `${i + 1} أشهر`,
      }));
    }
  };

  return (
    <div>
      {/* Header Section */}
      <Box mb="8">
        <HStack spacing="8" align="flex-start">
          {/* Title Section */}
          <VStack align="flex-start" spacing="2" flex="1" minW="300px">
            <Heading size="lg" className="stake-heading-3">
              إدارة السلف
            </Heading>
            <Text color="gray.600" fontSize="lg">
              إدارة سلف الموظفين وتتبع الأقساط
            </Text>
          </VStack>
        </HStack>
      </Box>

      {/* Filters Section */}
      <Box mb="6">
        <HStack spacing="3" align="center" w="100%">
          {/* Search */}
          <InputGroup flex="2" minW="250px">
            <InputRightElement>
              <Icon as={FiSearch} color="var(--stake-text-muted)" />
            </InputRightElement>
            <Input
              placeholder="البحث بالاسم أو الكود..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="stake-input"
              borderRadius="xl"
              height="44px"
              _focus={{
                borderColor: "var(--stake-border-accent)",
                boxShadow: "0 0 0 2px rgba(20, 117, 225, 0.2)"
              }}
              _hover={{
                borderColor: "var(--stake-border-accent)"
              }}
            />
          </InputGroup>

          {/* Status Filter */}
          <Select
            placeholder="جميع الحالات"
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="stake-input"
            borderRadius="xl"
            height="44px"
            minW="200px"
            _focus={{
              borderColor: "var(--stake-border-accent)",
              boxShadow: "0 0 0 2px rgba(20, 117, 225, 0.2)"
            }}
            _hover={{
              borderColor: "var(--stake-border-accent)"
            }}
          >
            <option value="">الكل</option>
            <option value="pending">معلقة</option>
            <option value="activated">مفعلة</option>
            <option value="completed">مكتملة</option>
            <option value="cancelled">ملغاة</option>
          </Select>

          {/* Salary Type Filter */}
          <Select
            placeholder="جميع أنواع الرواتب"
            value={salaryTypeFilter}
            onChange={(e) => setSalaryTypeFilter(e.target.value)}
            className="stake-input"
            borderRadius="xl"
            height="44px"
            minW="200px"
            _focus={{
              borderColor: "var(--stake-border-accent)",
              boxShadow: "0 0 0 2px rgba(20, 117, 225, 0.2)"
            }}
            _hover={{
              borderColor: "var(--stake-border-accent)"
            }}
          >
            <option value="">الكل</option>
            <option value="Weekly">أسبوعي</option>
            <option value="Monthly">شهري</option>
          </Select>

          {/* Clear Filters */}
          <IconButton
            icon={<FiX />}
            variant="outline"
            colorScheme="red"
            size="md"
            onClick={() => {
              setSearchTerm('');
              setStatusFilter('');
              setSalaryTypeFilter('');
            }}
            w="44px"
            h="44px"
            className="stake-input"
            borderRadius="xl"
            _hover={{
              bg: "var(--stake-bg-hover)",
              borderColor: "var(--stake-border-accent)"
            }}
            _active={{
              bg: "var(--stake-bg-card)"
            }}
          />

          {/* Add Button */}
          <Button
            leftIcon={<FiPlus />}
            className="stake-btn-primary"
            size="md"
            onClick={onAddModalOpen}
            h="44px"
            fontWeight="600"
            whiteSpace="nowrap"
            px="6"
            minW="fit-content"
            overflow="hidden"
            textOverflow="ellipsis"
          >
            إضافة سلفة جديدة
          </Button>

        </HStack>
      </Box>

      {/* Main Table */}
      <Box className="stake-card" overflow="hidden">
        <Box p="6">
          <HStack justify="space-between" mb="4">
            <Heading size="md" className="stake-heading-3">جدول السلف</Heading>
          </HStack>
          {loading && advances.length === 0 ? (
            <Center py="20">
              <VStack spacing="4">
                <Spinner size="xl" color="green.500" />
                <Text color="gray.600">جاري تحميل البيانات...</Text>
              </VStack>
            </Center>
          ) : filteredAdvances.length === 0 ? (
            <Center py="20">
              <VStack spacing="4">
                <Icon as={FiDollarSign} boxSize="16" color="gray.400" />
                <Text color="gray.600" fontSize="lg">لا توجد سلف مسجلة</Text>
                <Text color="gray.500" fontSize="sm">
                  اضغط على "إضافة سلفة جديدة" لإنشاء سلفة
                </Text>
              </VStack>
            </Center>
          ) : (
            <TableContainer maxH="70vh" overflowY="auto" className="stake-table main-content">
              <Table variant="simple" size="md" className="stake-table main-content">
                <Thead position="sticky" top="0" bg="var(--stake-bg-primary)" zIndex="1" boxShadow="var(--stake-shadow-sm)">
                  <Tr>
                    <Th>اسم الموظف</Th>
                    <Th>نوع الراتب</Th>
                    <Th>مبلغ السلفة</Th>
                    <Th>المدة</Th>
                    <Th>قسط السلفة</Th>
                    <Th>الحالة</Th>
                    <Th>تاريخ الإنشاء</Th>
                    <Th>الإجراءات</Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {filteredAdvances.map((advance) => (
                    <Tr key={advance.id} onDoubleClick={() => handleViewDetails(advance)} cursor="pointer" title="اضغط مرتين لعرض التفاصيل">
                      <Td>
                        <HStack spacing="3">
                          <Avatar size="sm" name={advance.employee_name} />
                          <VStack align="start" spacing="0">
                            <Text fontWeight="medium" fontSize="sm">{advance.employee_name}</Text>
                            <Text fontSize="xs" color="gray.500">
                              {advance.employee_code}
                            </Text>
                          </VStack>
                        </HStack>
                      </Td>
                      <Td>
                        <Badge colorScheme={advance.salary_type === 'Weekly' ? 'purple' : 'blue'} variant="subtle" px="2" py="1" borderRadius="md">
                          {advance.salary_type === 'Weekly' ? 'أسبوعي' : 'شهري'}
                        </Badge>
                      </Td>
                      <Td fontWeight="bold" color="white">{fmtCurrency(advance.advance_amount)}</Td>
                      <Td color="white">
                        {advance.duration} {advance.duration_type === 'weekly' ? 'أسبوع' : 'شهر'}
                      </Td>
                      <Td color="white">{fmtCurrency(advance.installment_amount)}</Td>
                      <Td>{getStatusBadge(advance.status)}</Td>
                      <Td color="white">
                        {new Date(advance.created_at).toLocaleDateString('ar-EG')}
                      </Td>
                      <Td>
                        <Menu>
                          <MenuButton
                            as={IconButton}
                            icon={<FiMoreVertical />}
                            variant="ghost"
                            size="sm"
                          />
                          <MenuList>
                            <MenuItem icon={<FiEye />} onClick={() => handleViewDetails(advance)}>
                              عرض التفاصيل
                            </MenuItem>
                            {advance.status === 'pending' && (
                              <>
                                <MenuItem
                                  icon={<FiCheckCircle />}
                                  onClick={() => handleActivateAdvance(advance.id)}
                                >
                                  تفعيل السلفة
                                </MenuItem>
                                <MenuDivider />
                                <MenuItem
                                  icon={<FiX />}
                                  onClick={() => handleCancelAdvance(advance.id)}
                                >
                                  إلغاء السلفة
                                </MenuItem>
                              </>
                            )}
                            {advance.status === 'activated' && (
                              <>
                                <MenuDivider />
                                <MenuItem
                                  icon={<FiX />}
                                  onClick={() => handleCancelAdvance(advance.id)}
                                  color="red.300"
                                >
                                  إلغاء السلفة
                                </MenuItem>
                              </>
                            )}
                            {advance.status === 'cancelled' && (
                              <>
                                <MenuDivider />
                                <MenuItem
                                  icon={<FiTrash2 />}
                                  onClick={() => handleDeleteAdvance(advance.id)}
                                  color="red.500"
                                >
                                  حذف السلفة
                                </MenuItem>
                              </>
                            )}
                          </MenuList>
                        </Menu>
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </TableContainer>
          )}
        </Box>
      </Box>

      {/* Add Advance Modal */}
      <Modal isOpen={isAddModalOpen} onClose={onAddModalClose} size="xl" isCentered>
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent bg="var(--stake-bg-primary)" border="none" borderRadius="3xl" boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" overflow="hidden">
          <ModalHeader
            bg="#0f212e"
            color="white"
            borderRadius="24px 24px 0 0"
            p="4"
            position="relative"
            boxShadow="0 4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack justify="space-between" align="center" w="100%">
              <HStack spacing="3">
                <Icon as={FiPlus} boxSize="5" />
                <Text fontSize="md" fontWeight="bold">
                  إضافة سلفة جديدة
                </Text>
              </HStack>
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                size="md"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)",
                  transform: "scale(1.1)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </HStack>
          </ModalHeader>
          <ModalBody p="8">
            <VStack spacing="4">
              <FormControl isRequired>
                <FormLabel className="stake-label">نوع الراتب</FormLabel>
                <RadioGroup
                  value={formData.salary_type}
                  onChange={(value) => {
                    const durationType = value === 'Weekly' ? 'weekly' : 'monthly';
                    const firstWorkingDay = calculateFirstWorkingDay(formData.created_date || new Date().toISOString().split('T')[0], value);
                    setFormData({ 
                      ...formData, 
                      salary_type: value, 
                      employee_id: '', 
                      duration_type: durationType,
                      start_date: firstWorkingDay
                    });
                  }}
                >
                  <Stack direction="row" spacing="4">
                    <Radio value="Weekly">أسبوعي</Radio>
                    <Radio value="Monthly">شهري</Radio>
                  </Stack>
                </RadioGroup>
              </FormControl>

              <FormControl isRequired>
                <FormLabel className="stake-label">اسم الموظف</FormLabel>
                <Select
                  placeholder="اختر الموظف"
                  value={formData.employee_id}
                  onChange={(e) => setFormData({ ...formData, employee_id: e.target.value })}
                  className="stake-input"
                  bg="#182935"
                  borderColor="#2f4553"
                  color="white"
                  _focus={{
                    borderColor: "#3b82f6",
                    boxShadow: "0 0 0 1px #3b82f6"
                  }}
                  _hover={{
                    borderColor: "#4a5568"
                  }}
                >
                  {filteredEmployees.map((emp) => (
                    <option key={emp.id} value={emp.id}>
                      {emp.name} ({emp.employee_code})
                    </option>
                  ))}
                </Select>
              </FormControl>

              {/* مبلغ السلفة، المدة، قسط السلفة في سطر واحد */}
              <SimpleGrid columns={3} spacing="4">
                <FormControl isRequired>
                  <FormLabel className="stake-label">مبلغ السلفة</FormLabel>
                  <NumberInput
                    value={formData.advance_amount}
                    onChange={(value) => setFormData({ ...formData, advance_amount: value })}
                    min={0}
                    precision={2}
                    className="stake-input"
                  >
                    <NumberInputField 
                      className="stake-input"
                      bg="#182935"
                      borderColor="#2f4553"
                      color="white"
                      _focus={{
                        borderColor: "#3b82f6",
                        boxShadow: "0 0 0 1px #3b82f6"
                      }}
                      _hover={{
                        borderColor: "#4a5568"
                      }}
                    />
                    <NumberInputStepper>
                      <NumberIncrementStepper 
                        bg="#2f4553"
                        borderColor="#4a5568"
                        color="white"
                        _hover={{
                          bg: "#4a5568"
                        }}
                        _active={{
                          bg: "#3b82f6"
                        }}
                      />
                      <NumberDecrementStepper 
                        bg="#2f4553"
                        borderColor="#4a5568"
                        color="white"
                        _hover={{
                          bg: "#4a5568"
                        }}
                        _active={{
                          bg: "#3b82f6"
                        }}
                      />
                    </NumberInputStepper>
                  </NumberInput>
                </FormControl>

                <FormControl isRequired>
                  <FormLabel className="stake-label">المدة</FormLabel>
                  <Select
                    placeholder="اختر المدة"
                    value={formData.duration}
                    onChange={(e) => setFormData({ ...formData, duration: e.target.value })}
                    className="stake-input"
                    bg="#182935"
                    borderColor="#2f4553"
                    color="white"
                    _focus={{
                      borderColor: "#3b82f6",
                      boxShadow: "0 0 0 1px #3b82f6"
                    }}
                    _hover={{
                      borderColor: "#4a5568"
                    }}
                  >
                    {getDurationOptions().map((option) => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </Select>
                </FormControl>

                <FormControl>
                  <FormLabel className="stake-label">قسط السلفة</FormLabel>
                  <Input
                    value={fmtCurrency(installmentAmount)}
                    isReadOnly
                    className="stake-input"
                    bg="#182935"
                    borderColor="#2f4553"
                    color="white"
                  />
                </FormControl>
              </SimpleGrid>

              {/* تاريخ إنشاء السلفة وتاريخ بداية السلفة */}
              <SimpleGrid columns={2} spacing="4">
                <FormControl>
                  <FormLabel className="stake-label">تاريخ إنشاء السلفة</FormLabel>
                  <Input
                    type="date"
                    value={formData.created_date}
                    onChange={(e) => {
                      const firstWorkingDay = calculateFirstWorkingDay(e.target.value, formData.salary_type);
                      setFormData({ ...formData, created_date: e.target.value, start_date: firstWorkingDay });
                    }}
                    className="stake-input"
                    bg="#182935"
                    borderColor="#2f4553"
                    color="white"
                    _focus={{
                      borderColor: "#3b82f6",
                      boxShadow: "0 0 0 1px #3b82f6"
                    }}
                    _hover={{
                      borderColor: "#4a5568"
                    }}
                  />
                </FormControl>

                <FormControl isRequired>
                  <FormLabel className="stake-label">
                    تاريخ بداية السلفة 
                    <Text as="span" fontSize="xs" color="gray.400" ml="2">
                      ({formData.salary_type === 'Weekly' ? 'أول يوم عمل في الأسبوع' : 'أول يوم عمل في الشهر'})
                    </Text>
                  </FormLabel>
                  <Input
                    type="date"
                    value={formData.start_date}
                    onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                    className="stake-input"
                    bg="#182935"
                    borderColor="#2f4553"
                    color="white"
                    _focus={{
                      borderColor: "#3b82f6",
                      boxShadow: "0 0 0 1px #3b82f6"
                    }}
                    _hover={{
                      borderColor: "#4a5568"
                    }}
                  />
                </FormControl>
              </SimpleGrid>

              <FormControl>
                <FormLabel className="stake-label">ملاحظات</FormLabel>
                <Textarea
                  value={formData.notes}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="ملاحظات إضافية..."
                  rows={3}
                  className="stake-input"
                  bg="#182935"
                  borderColor="#2f4553"
                  color="white"
                  _focus={{
                    borderColor: "#3b82f6",
                    boxShadow: "0 0 0 1px #3b82f6"
                  }}
                  _hover={{
                    borderColor: "#4a5568"
                  }}
                />
              </FormControl>
            </VStack>
          </ModalBody>
          <ModalFooter 
            display="flex" 
            justifyContent="flex-end" 
            gap="3"
            bg="#0f212e"
            borderRadius="0 0 24px 24px"
            p="4"
            borderTop="1px solid"
            borderColor="#2f4553"
          >
            <HStack spacing="3">
              <Button className="stake-btn-secondary" onClick={onAddModalClose}>
                إلغاء
              </Button>
              <Button
                className="stake-btn-primary"
                onClick={() => handleCreateAdvance(false)}
                isLoading={loading}
              >
                حفظ
              </Button>
              <Button
                className="stake-btn-success"
                onClick={() => handleCreateAdvance(true)}
                isLoading={loading}
              >
                حفظ وتفعيل
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Details Modal */}
      <Modal isOpen={isDetailsModalOpen} onClose={onDetailsModalClose} size="4xl" isCentered>
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent bg="var(--stake-bg-primary)" border="none" borderRadius="3xl" boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" overflow="hidden">
          <ModalHeader
            bg="#0f212e"
            color="white"
            borderRadius="24px 24px 0 0"
            p="4"
            position="relative"
            boxShadow="0 4px 20px rgba(0, 0, 0, 0.4)"
          >
            <VStack spacing="4" align="center" w="100%" position="relative">
              <HStack spacing="3" align="center" justify="center" w="100%">
                <Text fontSize="lg" fontWeight="bold" color="white">
                  تفاصيل السلفة
                </Text>
              </HStack>
              {selectedAdvance && (
                <HStack spacing="6" align="center" justify="center">
                  <HStack spacing="2">
                    <Icon as={FiUser} color="blue.300" boxSize="4" />
                    <Text fontSize="sm" color="gray.300">{selectedAdvance.employee_name}</Text>
                  </HStack>
                  <HStack spacing="2">
                    <Icon as={FiHash} color="green.300" boxSize="4" />
                    <Text fontSize="sm" color="gray.300">{selectedAdvance.employee_code}</Text>
                  </HStack>
                  <HStack spacing="2">
                    <Icon as={FiDollarSign} color="orange.300" boxSize="4" />
                    <Badge 
                      colorScheme={selectedAdvance.salary_type === 'Weekly' ? 'purple' : 'blue'}
                      variant="solid"
                      px="2"
                      py="1"
                      borderRadius="full"
                      fontSize="xs"
                      fontWeight="bold"
                    >
                      {selectedAdvance.salary_type === 'Weekly' ? 'أسبوعي' : 'شهري'}
                    </Badge>
                  </HStack>
                </HStack>
              )}
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                size="md"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)",
                  transform: "scale(1.1)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </VStack>
          </ModalHeader>
          <ModalBody p="8">
            {selectedAdvance && (
              <VStack spacing="6" align="stretch">
                {/* Basic Info */}
                <Box 
                  bg="#0f212e"
                  border="1px solid" 
                  borderColor="#3e5665" 
                  borderRadius="xl" 
                  p="6"
                >
                  <SimpleGrid columns={2} spacing="4">
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">اسم الموظف:</Text>
                      <Text color="white">{selectedAdvance.employee_name}</Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">نوع الراتب:</Text>
                      <Badge colorScheme={selectedAdvance.salary_type === 'Weekly' ? 'purple' : 'blue'} variant="solid">
                        {selectedAdvance.salary_type === 'Weekly' ? 'أسبوعي' : 'شهري'}
                      </Badge>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">مبلغ السلفة:</Text>
                      <Text fontWeight="bold" color="green.300">
                        {fmtCurrency(selectedAdvance.advance_amount)}
                      </Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">المدة:</Text>
                      <Text color="white">
                        {selectedAdvance.duration} {selectedAdvance.duration_type === 'weekly' ? 'أسبوع' : 'شهر'}
                      </Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">قسط السلفة:</Text>
                      <Text fontWeight="bold" color="white">{fmtCurrency(selectedAdvance.installment_amount)}</Text>
                    </HStack>
                    <HStack justify="space-between">
                      <Text fontWeight="bold" color="gray.300">الحالة:</Text>
                      {getStatusBadge(selectedAdvance.status)}
                    </HStack>
                  </SimpleGrid>
                </Box>

                {/* Installments Table */}
                <Box>
                  <Text fontWeight="bold" mb="4" color="white" fontSize="lg">الأقساط:</Text>
                  {selectedAdvance.installments && selectedAdvance.installments.length > 0 ? (
                    <TableContainer>
                      <Table size="sm" variant="simple" bg="#182935" borderRadius="lg" overflow="hidden">
                        <Thead bg="#0f212e">
                          <Tr>
                            <Th color="white">رقم القسط</Th>
                            <Th color="white">من</Th>
                            <Th color="white">إلى</Th>
                            <Th color="white">المبلغ</Th>
                            <Th color="white">الحالة</Th>
                          </Tr>
                        </Thead>
                        <Tbody>
                          {selectedAdvance.installments.map((installment) => (
                            <Tr key={installment.id} _hover={{ bg: "#2f4553" }} transition="all 0.2s">
                              <Td color="white">{installment.installment_number}</Td>
                              <Td color="white">{new Date(installment.period_start).toLocaleDateString('ar-EG')}</Td>
                              <Td color="white">{new Date(installment.period_end).toLocaleDateString('ar-EG')}</Td>
                              <Td color="white" fontWeight="bold">{fmtCurrency(installment.amount)}</Td>
                              <Td>
                                <Badge colorScheme={installment.is_paid ? 'green' : 'yellow'} variant="solid">
                                  {installment.is_paid ? 'مدفوع' : 'غير مدفوع'}
                                </Badge>
                              </Td>
                            </Tr>
                          ))}
                        </Tbody>
                      </Table>
                    </TableContainer>
                  ) : (
                    <Text color="gray.500" textAlign="center" py="8">لا توجد أقساط مسجلة</Text>
                  )}
                </Box>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter 
            display="flex" 
            justifyContent="flex-end" 
            gap="3"
            bg="#0f212e"
            borderRadius="0 0 24px 24px"
            p="4"
            borderTop="1px solid"
            borderColor="#2f4553"
          >
            <Button className="stake-btn-secondary" onClick={onDetailsModalClose}>
              إغلاق
            </Button>
            {selectedAdvance && (selectedAdvance.status === 'pending' || selectedAdvance.status === 'activated') && (
              <Button
                className="stake-btn-secondary"
                colorScheme="red"
                onClick={() => {
                  onDetailsModalClose();
                  handleCancelAdvance(selectedAdvance.id);
                }}
                isLoading={loading}
              >
                إلغاء السلفة
              </Button>
            )}
            {selectedAdvance && selectedAdvance.status === 'cancelled' && (
              <Button
                className="stake-btn-secondary"
                colorScheme="red"
                onClick={() => {
                  onDetailsModalClose();
                  handleDeleteAdvance(selectedAdvance.id);
                }}
                isLoading={loading}
              >
                حذف السلفة
              </Button>
            )}
          </ModalFooter>
        </ModalContent>
      </Modal>
    </div>
  );
};

export default PremiumAdvances;

