import React, { useEffect, useState } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Text,
  VStack,
  HStack,
  Grid,
  GridItem,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  Slider,
  SliderTrack,
  SliderFilledTrack,
  SliderThumb,
  Switch as CSwitch,
  Button,
  useToast,
  Divider,
  Icon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody
} from '@chakra-ui/react';
import { SaveOutlined, FontSizeOutlined } from '@ant-design/icons';
import { useSettings } from '../contexts/SettingsContext';

const NewAppearanceSettings = () => {
  const toast = useToast();
  const { updateSettings, reloadSettings } = useSettings();

  const [loading, setLoading] = useState(false);
  const [tempSettings, setTempSettings] = useState({});

  // Dark theme tokens
  const cardBg = '#0f212e';
  const cardBorder = '#3e5665';
  const headerBg = '#102a3a';
  const headerText = '#ffffff';
  const subText = '#a0aec0';
  const inputBg = '#0f212e';
  const inputText = '#e2e8f0';
  const inputBorder = '#3e5665';

  const [isSystemFontModalOpen, setIsSystemFontModalOpen] = useState(false);
  const [isTableFontModalOpen, setIsTableFontModalOpen] = useState(false);

  const arabicFonts = [
    { value: 'Cairo', label: 'Cairo', preview: 'نظام إدارة الرواتب' },
    { value: 'Tajawal', label: 'Tajawal', preview: 'نظام إدارة الرواتب' },
    { value: 'Amiri', label: 'Amiri', preview: 'نظام إدارة الرواتب' },
    { value: 'Noto Sans Arabic', label: 'Noto Sans Arabic', preview: 'نظام إدارة الرواتب' },
    { value: 'Changa', label: 'Changa', preview: 'نظام إدارة الرواتب' },
    { value: 'Lateef', label: 'Lateef', preview: 'نظام إدارة الرواتب' },
    { value: 'Scheherazade New', label: 'Scheherazade New', preview: 'نظام إدارة الرواتب' },
    { value: 'Markazi Text', label: 'Markazi Text', preview: 'نظام إدارة الرواتب' },
    { value: 'Harmattan', label: 'Harmattan', preview: 'نظام إدارة الرواتب' },
    { value: 'Lalezar', label: 'Lalezar', preview: 'نظام إدارة الرواتب' },
    { value: 'Mada', label: 'Mada', preview: 'نظام إدارة الرواتب' },
    { value: 'Mirza', label: 'Mirza', preview: 'نظام إدارة الرواتب' },
    { value: 'Rasa', label: 'Rasa', preview: 'نظام إدارة الرواتب' },
    { value: 'Aref Ruqaa', label: 'Aref Ruqaa', preview: 'نظام إدارة الرواتب' },
    { value: 'Kufam', label: 'Kufam' },
    { value: 'Lemonada', label: 'Lemonada' },
    { value: 'Baloo Bhaijaan 2', label: 'Baloo Bhaijaan 2' },
    { value: 'Readex Pro', label: 'Readex Pro' },
    { value: 'IBM Plex Sans Arabic', label: 'IBM Plex Sans Arabic' }
  ];

  const loadAppearanceSettings = async () => {
    try {
      setLoading(true);
      const response = await fetch(getApiUrl('/api/comprehensive_settings_api.php?action=get_settings_by_category&category=appearance'));
      const data = await response.json();
      if (data.success) {
        const s = {};
        data.settings.forEach(setting => { s[setting.setting_key] = setting.setting_value; });
        const loaded = {
          fontFamily: s.font_family || 'Cairo',
          tableFontFamily: s.table_font_family || 'Cairo',
          tableFontSize: parseInt(s.table_font_size) || 14,
          tableFontWeight: parseInt(s.table_font_weight) || 600,
          showEnglishKeys: s.show_english_keys === 'true' || s.show_english_keys === '1'
        };
        setTempSettings(loaded);
        if (loaded.fontFamily) applyFont(loaded.fontFamily);
        applyTableSettings(loaded);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadAppearanceSettings(); }, []);

  const applyFont = (fontFamily) => {
    document.documentElement.style.setProperty('--font-family', `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`);
    document.body.style.fontFamily = `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
    const root = document.getElementById('root');
    if (root) root.style.fontFamily = `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
  };

  const applyTableSettings = (s) => {
    if (s.tableFontFamily) document.documentElement.style.setProperty('--table-font-family', `'${s.tableFontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`);
    if (s.tableFontSize) document.documentElement.style.setProperty('--table-font-size', `${s.tableFontSize}px`);
    if (s.tableFontWeight) document.documentElement.style.setProperty('--table-font-weight', s.tableFontWeight);
    if (s.showEnglishKeys !== undefined) window.dispatchEvent(new CustomEvent('englishKeysToggled', { detail: { showEnglishKeys: s.showEnglishKeys } }));
  };

  const saveSettings = async () => {
    if (!tempSettings || Object.keys(tempSettings).length === 0) {
      toast({ title: 'لا توجد تغييرات للحفظ', status: 'info' });
      return;
    }
    setLoading(true);
    try {
      if (tempSettings.fontFamily) applyFont(tempSettings.fontFamily);
      applyTableSettings(tempSettings);

      const settingsToUpdate = Object.entries(tempSettings).map(([key, value]) => {
        let dbKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();
        if (key === 'showEnglishKeys') dbKey = 'show_english_keys';
        return { key: dbKey, value: value };
      });

      const response = await fetch(getApiUrl('/api/comprehensive_settings_api.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_multiple_settings', settings: settingsToUpdate })
      });
      const data = await response.json();
      if (data.success) {
        toast({ title: 'تم حفظ إعدادات المظهر', status: 'success' });
        updateSettings(tempSettings);
        window.dispatchEvent(new CustomEvent('themeUpdated', { detail: tempSettings }));
        await reloadSettings();
      } else {
        throw new Error(data.message || 'فشل الحفظ');
      }
    } catch (e) {
      console.error(e);
      toast({ title: 'فشل في حفظ الإعدادات', status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const currentFontLabel = (val) => arabicFonts.find(f => f.value === val)?.label || 'Cairo';

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* Font Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={FontSizeOutlined} color="blue.300" />
              <Heading size="sm" color={headerText}>إعدادات الخط العام</Heading>
            </HStack>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <Grid templateColumns={{ base: '1fr', lg: '1fr 1fr' }} gap={6}>
              <GridItem>
                <FormControl>
                  <FormLabel color={subText}>خط النظام العام</FormLabel>
                  <Button onClick={() => setIsSystemFontModalOpen(true)} bg={inputBg} color={inputText} border="1px solid" borderColor={inputBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>
                    {currentFontLabel(tempSettings.fontFamily || 'Cairo')}
                  </Button>
                </FormControl>
              </GridItem>
              <GridItem>
                <FormControl>
                  <FormLabel color={subText}>معاينة الخط</FormLabel>
                  <Box mt="2" p="4" border="1px solid" borderColor={cardBorder} borderRadius="md" bg="#0b1a24" textAlign="center"
                    style={{ fontFamily: `'${tempSettings.fontFamily || 'Cairo'}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif` }}>
                    <Text color={inputText}>مرحباً بك في نظام إدارة الرواتب والأجور</Text>
                    <Text color={subText}>Welcome to TimePay Management System</Text>
                  </Box>
                </FormControl>
              </GridItem>
            </Grid>
          </CardBody>
        </Card>

        {/* Table Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <Heading size="sm" color={headerText}>إعدادات الجداول</Heading>
          </CardHeader>
          <CardBody bg="#1b2b38">
            <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
              <FormControl>
                <FormLabel color={subText}>اسم الخط</FormLabel>
                <Button onClick={() => setIsTableFontModalOpen(true)} bg={inputBg} color={inputText} border="1px solid" borderColor={inputBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>
                  {tempSettings.tableFontFamily === 'system' ? 'خط النظام العام' : currentFontLabel(tempSettings.tableFontFamily || 'Cairo')}
                </Button>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>مقاس الخط: {tempSettings.tableFontSize || 14}px</FormLabel>
                <Slider 
                  min={10} 
                  max={50} 
                  value={tempSettings.tableFontSize || 14} 
                  onChange={(v) => setTempSettings(s => ({ ...s, tableFontSize: v }))}
                  colorScheme="blue"
                >
                  <SliderTrack bg="gray.600">
                    <SliderFilledTrack bg="blue.400" />
                  </SliderTrack>
                  <SliderThumb bg="blue.400" />
                </Slider>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>وزن الخط: {tempSettings.tableFontWeight || 600}</FormLabel>
                <Slider 
                  min={100} 
                  max={900} 
                  step={100} 
                  value={tempSettings.tableFontWeight || 600} 
                  onChange={(v) => setTempSettings(s => ({ ...s, tableFontWeight: v }))}
                  colorScheme="blue"
                >
                  <SliderTrack bg="gray.600">
                    <SliderFilledTrack bg="blue.400" />
                  </SliderTrack>
                  <SliderThumb bg="blue.400" />
                </Slider>
              </FormControl>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>إظهار المفاتيح الإنجليزية</FormLabel>
                <CSwitch 
                  isChecked={tempSettings.showEnglishKeys !== undefined ? tempSettings.showEnglishKeys : true} 
                  onChange={(e) => setTempSettings(s => ({ ...s, showEnglishKeys: e.target.checked }))}
                  colorScheme="blue"
                />
              </FormControl>
            </SimpleGrid>

            <Divider my="4" borderColor={cardBorder} />
            <Text color={inputText} fontWeight="semibold">معاينة تنسيق الجدول</Text>
            <Box mt="2" border="1px solid" borderColor={cardBorder} borderRadius="md" overflow="hidden">
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ backgroundColor: '#102a3a' }}>
                    {['اسم الموظف', 'الراتب الأساسي', 'القسم'].map((h, idx) => (
                      <th key={idx} style={{ padding: '12px 8px', color: '#e2e8f0', textAlign: 'right', borderBottom: `1px solid ${cardBorder}`, fontFamily: tempSettings.tableFontFamily === 'system' ? `'${tempSettings.fontFamily || 'Cairo'}'` : `'${tempSettings.tableFontFamily || 'Cairo'}'`, fontSize: `${tempSettings.tableFontSize || 14}px`, fontWeight: tempSettings.tableFontWeight || 600 }}>
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {[
                    ['أحمد محمد علي', '5,000 ج.م.', 'المحاسبة'],
                    ['فاطمة أحمد حسن', '4,500 ج.م.', 'الموارد البشرية']
                  ].map((row, i) => (
                    <tr key={i} style={{ backgroundColor: i % 2 ? '#0f212e' : '#0b1a24' }}>
                      {row.map((cell, j) => (
                        <td key={j} style={{ padding: '10px 8px', color: '#e2e8f0', borderBottom: `1px solid ${cardBorder}`, fontFamily: tempSettings.tableFontFamily === 'system' ? `'${tempSettings.fontFamily || 'Cairo'}'` : `'${tempSettings.tableFontFamily || 'Cairo'}'`, fontSize: `${tempSettings.tableFontSize || 14}px`, fontWeight: 400 }}>
                          {cell}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </Box>
          </CardBody>
        </Card>

        {/* Save Button */}
        <HStack justify="center" bg="#0b1a24" p="4" borderRadius="xl">
          <Button onClick={saveSettings} isLoading={loading} leftIcon={<Icon as={SaveOutlined} />} bg="#1475e1" _hover={{ bg: '#0e63c2' }} color="white">
            {loading ? 'جاري الحفظ...' : 'حفظ إعدادات المظهر'}
          </Button>
        </HStack>
      </VStack>

      {/* System Font Modal */}
      <Modal isOpen={isSystemFontModalOpen} onClose={() => setIsSystemFontModalOpen(false)} size="full">
        <ModalOverlay bg="rgba(0,0,0,0.7)" />
        <ModalContent bg={cardBg}>
          <ModalHeader color={headerText}>اختر خط النظام العام</ModalHeader>
          <ModalCloseButton color={headerText} />
          <ModalBody>
            <Box maxH="80vh" overflowY="auto" border="1px solid" borderColor={cardBorder} borderRadius="lg" p="4"
              sx={{
                '::-webkit-scrollbar': { width: '10px' },
                '::-webkit-scrollbar-track': { background: '#0b1a24', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb': { background: '#3e5665', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb:hover': { background: '#4f6f81' }
              }}
            >
              <VStack align="stretch" spacing={3}>
                {arabicFonts.map(f => (
                  <Box
                    key={f.value}
                    p="4"
                    bg={cardBg}
                    border="1px solid"
                    borderColor={cardBorder}
                    borderRadius="lg"
                    cursor="pointer"
                    _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                    onClick={() => { setTempSettings(s => ({ ...s, fontFamily: f.value })); setIsSystemFontModalOpen(false); }}
                  >
                    <HStack justify="space-between" align="center" spacing={4}>
                      <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                        {f.label}
                      </Text>
                      <Text 
                        fontFamily={f.value}
                        color={inputText}
                        fontSize="xl"
                        lineHeight="1.6"
                        flex="1"
                        textAlign="right"
                      >
                        {f.preview || 'نظام إدارة الرواتب'}
                      </Text>
                    </HStack>
                  </Box>
                ))}
              </VStack>
            </Box>
          </ModalBody>
        </ModalContent>
      </Modal>

      {/* Table Font Modal */}
      <Modal isOpen={isTableFontModalOpen} onClose={() => setIsTableFontModalOpen(false)} size="full">
        <ModalOverlay bg="rgba(0,0,0,0.7)" />
        <ModalContent bg={cardBg}>
          <ModalHeader color={headerText}>اختر خط الجداول</ModalHeader>
          <ModalCloseButton color={headerText} />
          <ModalBody>
            <Box maxH="80vh" overflowY="auto" border="1px solid" borderColor={cardBorder} borderRadius="lg" p="4"
              sx={{
                '::-webkit-scrollbar': { width: '10px' },
                '::-webkit-scrollbar-track': { background: '#0b1a24', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb': { background: '#3e5665', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb:hover': { background: '#4f6f81' }
              }}
            >
              <VStack align="stretch" spacing={3}>
                <Box
                  p="4"
                  bg={cardBg}
                  border="1px solid"
                  borderColor={cardBorder}
                  borderRadius="lg"
                  cursor="pointer"
                  _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                  onClick={() => { setTempSettings(s => ({ ...s, tableFontFamily: 'system' })); setIsTableFontModalOpen(false); }}
                >
                  <HStack justify="space-between" align="center" spacing={4}>
                    <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                      خط النظام العام
                    </Text>
                    <Text 
                      color={inputText}
                      fontSize="xl"
                      lineHeight="1.6"
                      flex="1"
                      textAlign="right"
                    >
                      نظام إدارة الرواتب
                    </Text>
                  </HStack>
                </Box>
                {arabicFonts.map(f => (
                  <Box
                    key={f.value}
                    p="4"
                    bg={cardBg}
                    border="1px solid"
                    borderColor={cardBorder}
                    borderRadius="lg"
                    cursor="pointer"
                    _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                    onClick={() => { setTempSettings(s => ({ ...s, tableFontFamily: f.value })); setIsTableFontModalOpen(false); }}
                  >
                    <HStack justify="space-between" align="center" spacing={4}>
                      <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                        {f.label}
                      </Text>
                      <Text 
                        fontFamily={f.value}
                        color={inputText}
                        fontSize="xl"
                        lineHeight="1.6"
                        flex="1"
                        textAlign="right"
                      >
                        {f.preview || 'نظام إدارة الرواتب'}
                      </Text>
                    </HStack>
                  </Box>
                ))}
              </VStack>
            </Box>
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default NewAppearanceSettings;
